        // the crop box's corner at the origin, /Rotate applied). x0..y1 are the crop
        // box in centipoints.
        long h = (long) 1677721600;
        long nh = (long) -1677721600;
        if (rot == 90) {
            Fx.MxSet(cx, CBase, (long) 0, h, h, (long) 0, Fx.FxOfInt(0 - y0), Fx.FxOfInt(0 - x0));
        }
        if (rot == 180) {
            Fx.MxSet(cx, CBase, nh, (long) 0, (long) 0, h, Fx.FxOfInt(x1), Fx.FxOfInt(0 - y0));
        }
        if (rot == 270) {
            Fx.MxSet(cx, CBase, (long) 0, nh, nh, (long) 0, Fx.FxOfInt(y1), Fx.FxOfInt(x1));
        }
        if ((rot != 90) && ((rot != 180) && (rot != 270))) {
            Fx.MxSet(cx, CBase, h, (long) 0, (long) 0, nh, Fx.FxOfInt(0 - x0), Fx.FxOfInt(y1));
        }
        return 0;
    }
    internal static int PcSave(emon.Port.Cells cx) {
        int d = emon.Port.CellsAt(cx, CDepth);
        if (d >= MaxGs) {
            PcWarnSet(cx, WStates);
            return 0;
        }
        PcCopyCells(cx, CStack + (d * GsStride), CCur, GsStride);
        emon.Port.CellsSet(cx, CDepth, d + 1);
        return 1;
    }
    internal static int PcRestore(emon.Port.Cells cx) {
        // Q: pops only what this stream pushed.
        int d = emon.Port.CellsAt(cx, CDepth);
        int @base = emon.Port.CellsAt(cx, CGsbase);
        if (d <= @base) {
            PcWarnSet(cx, WStates);
            return 0;
        }
        PcCopyCells(cx, CCur, CStack + ((d - 1) * GsStride), GsStride);
        emon.Port.CellsSet(cx, CDepth, d - 1);
        return 1;
    }
    internal static int PcUpdateM(emon.Port.Cells cx) {
        // M = Tm x CTM, the matrix from text space to page space.
        Fx.MxMul(cx, CM, CTm, CCur + GCtm);
        return 0;
    }
    internal static int PcAdvance(emon.Port.Cells cx, long dx, long dy) {
        // Move the text position by (dx, dy) in TEXT space: Tm and M both translate
        // by the vector through their own linear parts.
        long ta = Fx.FxGet(cx, CTm);
        long tb = Fx.FxGet(cx, CTm + 2);
        long tc = Fx.FxGet(cx, CTm + 4);
        long td = Fx.FxGet(cx, CTm + 6);
        long te = Fx.FxGet(cx, CTm + 8);
        long tf = Fx.FxGet(cx, CTm + 10);
        long ma = Fx.FxGet(cx, CM);
        long mb = Fx.FxGet(cx, CM + 2);
        long mc = Fx.FxGet(cx, CM + 4);
        long md = Fx.FxGet(cx, CM + 6);
        long me = Fx.FxGet(cx, CM + 8);
        long mf = Fx.FxGet(cx, CM + 10);
        Fx.FxPut(cx, CTm + 8, Fx.FxClamp(unchecked(te + unchecked(Fx.FxMul(dx, ta) + Fx.FxMul(dy, tc)))));
        Fx.FxPut(cx, CTm + 10, Fx.FxClamp(unchecked(tf + unchecked(Fx.FxMul(dx, tb) + Fx.FxMul(dy, td)))));
        Fx.FxPut(cx, CM + 8, Fx.FxClamp(unchecked(me + unchecked(Fx.FxMul(dx, ma) + Fx.FxMul(dy, mc)))));
        Fx.FxPut(cx, CM + 10, Fx.FxClamp(unchecked(mf + unchecked(Fx.FxMul(dx, mb) + Fx.FxMul(dy, md)))));
        return 0;
    }
    internal static int PcTd(emon.Port.Cells cx, long tx, long ty) {
        // Td: the line matrix moves by (tx, ty) in its own space; the text matrix
        // starts over there.
        Fx.MxTranslate(cx, CTmp, tx, ty);
        Fx.MxMul(cx, CTlm, CTmp, CTlm);
        Fx.MxCopy(cx, CTm, CTlm);
        return 0;
    }
    internal static int PcSetTm(emon.Port.Cells cx, long a, long b, long c, long d, long e, long f) {
        Fx.MxSet(cx, CTm, a, b, c, d, e, f);
        Fx.MxCopy(cx, CTlm, CTm);
        return 0;
    }
    internal static int PcNextLine(emon.Port.Cells cx) {
        // T*: down by the leading.
        long tl = Fx.FxGet(cx, CCur + GTl);
        PcTd(cx, (long) 0, ((long) 0) - tl);
        return 0;
    }
    internal static int PcByte(long v) {
        // A colour component in 0..1 (an Fx) as 0..255, rounded.
        int n = Fx.FxRound(Fx.FxMul(v, Fx.FxOfInt(255)));
        if (n < 0) {
            return 0;
        }
        if (n > 255) {
            return 255;
        }
        return n;
    }
    internal static int PcRgb(int r, int g, int bl) {
        return (r * 65536) + ((g * 256) + bl);
    }
    internal static int PcSetColor(emon.Port.Cells cx, emon.Port.Cells ox, int n) {
        // sc / scn / g / rg / k: set the fill colour from n operands by their count
        // (1 gray, 3 RGB, 4 CMYK). A component list of another length (a pattern, an
        // Indexed or Separation colour) leaves the colour as it was.
        long o0 = PcNum(ox, n, 0);
        long o1 = PcNum(ox, n, 1);
        long o2 = PcNum(ox, n, 2);
        long o3 = PcNum(ox, n, 3);
        long one = Fx.FxOne();
        if (n == 1) {
            int gy = PcByte(o0);
            emon.Port.CellsSet(cx, CCur + GColor, PcRgb(gy, gy, gy));
            return 0;
        }
        if (n == 3) {
            emon.Port.CellsSet(cx, CCur + GColor, PcRgb(PcByte(o0), PcByte(o1), PcByte(o2)));
            return 0;
        }
        if (n == 4) {
            long kk = one - o3;
            emon.Port.CellsSet(cx, CCur + GColor, PcRgb(PcByte(Fx.FxMul(one - o0, kk)), PcByte(Fx.FxMul(one - o1, kk)), PcByte(Fx.FxMul(one - o2, kk))));
            return 0;
        }
        return 0;
    }
    internal static int PcDictLookup(emon.Port.Cells ar, int dict, emon.Port.Cells ox, int ns, int nl) {
        // The value (unresolved) under the key spelled ox[ns, ns+nl), or 0. The
        // last of a repeated key wins.
        int k = Pdflex.PlFirst(ar, dict);
        int v = 0;
        int found = 0;
        int same = 0;
        int i = 0;
        if (Pdflex.PlKindOf(ar, dict) != 7) {
            return 0;
        }
        while (k != 0) {
            v = Pdflex.PlNext(ar, k);
            if ((Pdflex.PlKindOf(ar, k) == 4) && (Pdflex.PlNameLen(ar, k) == nl)) {
                same = 1;
                i = 0;
                while ((same == 1) && (i < nl)) {
                    if (Pdflex.PlNameByte(ar, k, i) != emon.Port.CellsAt(ox, ns + i)) {
                        same = 0;
                    }
                    i += 1;
                }
                if (same == 1) {
                    found = v;
                }
            }
            if (v == 0) {
                k = 0;
            } else {
                k = Pdflex.PlNext(ar, v);
            }
        }
        return found;
    }
    internal static int PcResEntry(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, int kindId, int ei) {
        // The UNRESOLVED entry named by operand ei (a name) in the current Resources'
        // sub-dictionary `kind-id` (`(pn-font)`, `(pn-x-object)`, ...), 0 when none.
        int res = emon.Port.CellsAt(cx, CRes);
        int ns = PcEa(ox, ei);
        int nl = PcEb(ox, ei);
        if (res == 0) {
            return 0;
        }
        int sub = Pdfdoc.PdDget(src, ar, dc, a, b, st, res, kindId);
        if (sub == 0) {
            return 0;
        }
        return PcDictLookup(ar, sub, ox, ns, nl);
    }
    internal static int PcFLoad(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int slot, int fh) {
        if (slot == 0) {
            return Pdffont.PfnLoad(src, ar, dc, a, b, st, f0, @out, fh);
        }
        if (slot == 1) {
            return Pdffont.PfnLoad(src, ar, dc, a, b, st, f1, @out, fh);
        }
        if (slot == 2) {
            return Pdffont.PfnLoad(src, ar, dc, a, b, st, f2, @out, fh);
        }
        return Pdffont.PfnLoad(src, ar, dc, a, b, st, f3, @out, fh);
    }
    internal static int PcFQ(emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int slot, int which) {
        // A font's metric: which 0 ascent, 1 descent, 2 vertical, 3 DW2 v, 4 DW2 w.
        if (slot == 0) {
            if (which == 0) {
                return Pdffont.PfnAscent(f0);
            }
            if (which == 1) {
                return Pdffont.PfnDescent(f0);
            }
            if (which == 2) {
                return Pdffont.PfnVertical(f0);
            }
            if (which == 3) {
                return Pdffont.PfnDw2V(f0);
            }
            return Pdffont.PfnDw2W(f0);
        }
        if (slot == 1) {
            if (which == 0) {
                return Pdffont.PfnAscent(f1);
            }
            if (which == 1) {
                return Pdffont.PfnDescent(f1);
            }
            if (which == 2) {
                return Pdffont.PfnVertical(f1);
            }
            if (which == 3) {
                return Pdffont.PfnDw2V(f1);
            }
            return Pdffont.PfnDw2W(f1);
        }
        if (slot == 2) {
            if (which == 0) {
                return Pdffont.PfnAscent(f2);
            }
            if (which == 1) {
                return Pdffont.PfnDescent(f2);
            }
            if (which == 2) {
                return Pdffont.PfnVertical(f2);
            }
            if (which == 3) {
                return Pdffont.PfnDw2V(f2);
            }
            return Pdffont.PfnDw2W(f2);
        }
        if (which == 0) {
            return Pdffont.PfnAscent(f3);
        }
        if (which == 1) {
            return Pdffont.PfnDescent(f3);
        }
        if (which == 2) {
            return Pdffont.PfnVertical(f3);
        }
        if (which == 3) {
            return Pdffont.PfnDw2V(f3);
        }
        return Pdffont.PfnDw2W(f3);
    }
    internal static int PcFCodeLen(emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int slot, int b0, int b1, int b2, int b3) {
        if (slot == 0) {
            return Pdffont.PfnCodeLen(f0, b0, b1, b2, b3);
        }
        if (slot == 1) {
            return Pdffont.PfnCodeLen(f1, b0, b1, b2, b3);
        }
        if (slot == 2) {
            return Pdffont.PfnCodeLen(f2, b0, b1, b2, b3);
        }
        return Pdffont.PfnCodeLen(f3, b0, b1, b2, b3);
    }
    internal static int PcFMap(emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int slot, int code) {
        // The code points of a code: their count (`pfn-map`).
        if (slot == 0) {
            return Pdffont.PfnMap(f0, code);
        }
        if (slot == 1) {
            return Pdffont.PfnMap(f1, code);
        }
        if (slot == 2) {
            return Pdffont.PfnMap(f2, code);
        }
        return Pdffont.PfnMap(f3, code);
    }
    internal static int PcFCp(emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int slot, int i) {
        if (slot == 0) {
            return Pdffont.PfnCp(f0, i);
        }
        if (slot == 1) {
            return Pdffont.PfnCp(f1, i);
        }
        if (slot == 2) {
            return Pdffont.PfnCp(f2, i);
        }
        return Pdffont.PfnCp(f3, i);
    }
    internal static int PcFHow(emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int slot) {
        if (slot == 0) {
            return Pdffont.PfnHowOf(f0);
        }
        if (slot == 1) {
            return Pdffont.PfnHowOf(f1);
        }
        if (slot == 2) {
            return Pdffont.PfnHowOf(f2);
        }
        return Pdffont.PfnHowOf(f3);
    }
    internal static int PcFWidth(emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int slot, int code) {
        if (slot == 0) {
            return Pdffont.PfnWidth(f0, code);
        }
        if (slot == 1) {
            return Pdffont.PfnWidth(f1, code);
        }
        if (slot == 2) {
            return Pdffont.PfnWidth(f2, code);
        }
        return Pdffont.PfnWidth(f3, code);
    }
    internal static int PcFontId(emon.Port.Cells cx, int key) {
        // The evidence id of a font dictionary: its index in the order the
        // document first showed it (-1 past 512 fonts).
        int n = emon.Port.CellsAt(cx, CNfont);
        int i = 0;
        while (i < n) {
            if (emon.Port.CellsAt(cx, CFids + i) == key) {
                return i;
            }
            i += 1;
        }
        if (n >= MaxFids) {
            return -1;
        }
        emon.Port.CellsSet(cx, CFids + n, key);
        emon.Port.CellsSet(cx, CNfont, n + 1);
        return n;
    }
    internal static int PcEnsureFont(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3) {
        // Make the current font (the graphics state's) resident in a slot and set
        // C_SLOT to it, -1 when there is none. A font is loaded once and kept; the
        // slot that has gone unused longest is the one replaced.
        int key = emon.Port.CellsAt(cx, CCur + GFont);
        int i = 0;
        int at = 0;
        int pick = 0;
        int best = 2147483647;
        int status = 0;
        int fid = 0;
        int clock = emon.Port.CellsAt(cx, CClock);
        if (key == 0) {
            emon.Port.CellsSet(cx, CSlot, -1);
            return 0;
        }
        clock += 1;
        emon.Port.CellsSet(cx, CClock, clock);
        while (i < 4) {
            at = CSlots + (i * SlotStride);
            if (emon.Port.CellsAt(cx, at + SKey) == key) {
                emon.Port.CellsSet(cx, at + SUse, clock);
                emon.Port.CellsSet(cx, CSlot, i);
                return 0;
            }
            if (emon.Port.CellsAt(cx, at + SUse) < best) {
                best = emon.Port.CellsAt(cx, at + SUse);
                pick = i;
            }
            i += 1;
        }
        at = CSlots + (pick * SlotStride);
        status = PcFLoad(src, ar, dc, a, b, st, @out, f0, f1, f2, f3, pick, key);
        if (Pdfsrc.PsMissed(src)) {
            emon.Port.CellsSet(cx, CAbort, 1);
            emon.Port.CellsSet(cx, at + SKey, 0);
            emon.Port.CellsSet(cx, CSlot, -1);
            return 0;
        }
        emon.Port.CellsSet(cx, at + SKey, key);
        emon.Port.CellsSet(cx, at + SUse, clock);
        emon.Port.CellsSet(cx, at + SStatus, status);
        fid = PcFontId(cx, key);
        emon.Port.CellsSet(cx, at + SId, fid);
        if (status == 0) {
            emon.Port.CellsSet(cx, at + SAsc, PcFQ(f0, f1, f2, f3, pick, 0));
            emon.Port.CellsSet(cx, at + SDesc, PcFQ(f0, f1, f2, f3, pick, 1));
            emon.Port.CellsSet(cx, at + SVert, PcFQ(f0, f1, f2, f3, pick, 2));
            emon.Port.CellsSet(cx, at + SDw2v, PcFQ(f0, f1, f2, f3, pick, 3));
            emon.Port.CellsSet(cx, at + SDw2w, PcFQ(f0, f1, f2, f3, pick, 4));
        } else {
            emon.Port.CellsSet(cx, at + SAsc, 0);
            emon.Port.CellsSet(cx, at + SDesc, 0);
            emon.Port.CellsSet(cx, at + SVert, 0);
        }
        emon.Port.CellsSet(cx, CSlot, pick);
        return 0;
    }
    internal static int PcTf(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, int n) {
        // Tf: the font named by operand 0 from the current Resources, at the size of
        // operand 1. The dictionary is resolved here and loaded at the first glyph.
        long size = PcNum(ox, n, 1);
        int fh = 0;
        int raw = 0;
        Fx.FxPut(cx, CCur + GFs, size);
        if ((n >= 1) && (PcKind(ox, 0) == KName)) {
            raw = PcResEntry(src, ar, dc, a, b, st, cx, ox, Pdfnames.PnFont(), 0);
            if (raw != 0) {
                fh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, raw);
            }
        }
        if (Pdfsrc.PsMissed(src)) {
            emon.Port.CellsSet(cx, CAbort, 1);
            return 0;
        }
        if (fh == 0) {
            PcWarnSet(cx, WFont);
        } else if (Pdflex.PlKindOf(ar, fh) != 7) {
            fh = 0;
            PcWarnSet(cx, WFont);
        }
        emon.Port.CellsSet(cx, CCur + GFont, fh);
        return 0;
    }
    internal static long PcMin4(long p, long q, long r, long s) {
        long m = p;
        if (q < m) {
            m = q;
        }
        if (r < m) {
            m = r;
        }
        if (s < m) {
            m = s;
        }
        return m;
    }
    internal static long PcMax4(long p, long q, long r, long s) {
        long m = p;
        if (q > m) {
            m = q;
        }
        if (r > m) {
            m = r;
        }
        if (s > m) {
            m = s;
        }
        return m;
    }
    internal static int PcGlyph(emon.Port.Cells cx, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int code, int ncode) {
        // One shown glyph: look the code up, put its cell in page space, record it,
        // advance the text position by its width, the character and word spacing.
        int slot = emon.Port.CellsAt(cx, CSlot);
        long fs = Fx.FxGet(cx, CCur + GFs);
        long th = Fx.FxGet(cx, CCur + GTh);
        long tc = Fx.FxGet(cx, CCur + GTc);
        long tw = Fx.FxGet(cx, CCur + GTw);
        long rise = Fx.FxGet(cx, CCur + GRise);
        int sat = 0;
        int cnt = 0;
        int cp0 = -1;
        int how = 5;
        int w = -1;
        int asc = 0;
        int desc = 0;
        int vert = 0;
        int dwv = -100000;
        int fid = -1;
        int tstart = -1;
        int i = 0;
        int idx = 0;
        if (slot >= 0) {
            sat = CSlots + (slot * SlotStride);
            fid = emon.Port.CellsAt(cx, sat + SId);
            if (emon.Port.CellsAt(cx, sat + SStatus) == 0) {
                cnt = PcFMap(f0, f1, f2, f3, slot, code);
                how = PcFHow(f0, f1, f2, f3, slot);
                w = PcFWidth(f0, f1, f2, f3, slot, code);
                asc = emon.Port.CellsAt(cx, sat + SAsc);
                desc = emon.Port.CellsAt(cx, sat + SDesc);
                vert = emon.Port.CellsAt(cx, sat + SVert);
                dwv = emon.Port.CellsAt(cx, sat + SDw2w);
            }
        }
        if (cnt > 0) {
            cp0 = PcFCp(f0, f1, f2, f3, slot, 0);
        }
        // A composite font's ToUnicode may say U+0000 or U+FFFD for a glyph it has no value
        // for (Skia does, for the parts of a Devanagari conjunct): that is no value.
        if ((cnt == 1) && ((cp0 == 0) || (cp0 == 65533))) {
            cnt = 0;
            cp0 = -1;
            how = 5;
        }
        if (w < 0) {
            w = 50000;
            PcWarnSet(cx, WWidth);
        }
        if ((asc == 0) && (desc == 0)) {
            asc = 800;
            desc = -200;
        }
        long wfx = Fx.FxMuldiv((long) w, fs, (long) 100000);
        long x0t = (long) 0;
        long x1t = (long) 0;
        long y0t = (long) 0;
        long y1t = (long) 0;
        if (vert == 0) {
            x1t = Fx.FxMul(wfx, th);
            y0t = unchecked(Fx.FxMuldiv((long) desc, fs, (long) 1000) + rise);
            y1t = unchecked(Fx.FxMuldiv((long) asc, fs, (long) 1000) + rise);
        } else {
            x0t = ((long) 0) - (wfx / ((long) 2));
            x1t = wfx / ((long) 2);
            y0t = unchecked(Fx.FxMuldiv((long) dwv, fs, (long) 100000) + rise);
            y1t = rise;
        }
        long p0x = Fx.MxX(cx, CM, x0t, y0t);
        long p0y = Fx.MxY(cx, CM, x0t, y0t);
        long p1x = Fx.MxX(cx, CM, x1t, y0t);
        long p1y = Fx.MxY(cx, CM, x1t, y0t);
        long p2x = Fx.MxX(cx, CM, x0t, y1t);
        long p2y = Fx.MxY(cx, CM, x0t, y1t);
        long p3x = Fx.MxX(cx, CM, x1t, y1t);
        long p3y = Fx.MxY(cx, CM, x1t, y1t);
        long ma = Fx.FxGet(cx, CM);
        long mb = Fx.FxGet(cx, CM + 2);
        long mc = Fx.FxGet(cx, CM + 4);
        long md = Fx.FxGet(cx, CM + 6);
        int size = Fx.FxRound(Fx.FxMul(Fx.FxHypot(mc, md), Fx.FxAbs(fs)));
        int rot = Fx.FxAtan2(((long) 0) - mb, ma);
        int bline = Fx.FxRound(Fx.MxY(cx, CM, (long) 0, rise));
        int g = Evidence.GlNew(gl, emon.Port.CellsAt(cx, CPage), cp0, fid, size, Fx.FxRound(PcMin4(p0x, p1x, p2x, p3x)), Fx.FxRound(PcMin4(p0y, p1y, p2y, p3y)), Fx.FxRound(PcMax4(p0x, p1x, p2x, p3x)), Fx.FxRound(PcMax4(p0y, p1y, p2y, p3y)));
        Evidence.GlSet(gl, g, Evidence.GfHow(), how);
        Evidence.GlSet(gl, g, Evidence.GfBaseline(), bline);
        Evidence.GlSet(gl, g, Evidence.GfRot(), rot);
        Evidence.GlSet(gl, g, Evidence.GfColor(), emon.Port.CellsAt(cx, CCur + GColor));
        Evidence.GlSet(gl, g, Evidence.GfAlpha(), emon.Port.CellsAt(cx, CCur + GAlpha));
        Evidence.GlSet(gl, g, Evidence.GfMode(), emon.Port.CellsAt(cx, CCur + GMode));
        Evidence.GlSet(gl, g, Evidence.GfArtifact(), emon.Port.CellsAt(cx, CCurart));
        Evidence.GlSet(gl, g, Evidence.GfMcid(), emon.Port.CellsAt(cx, CCurmcid));
        if (cnt > 1) {
            i = 0;
            while (i < cnt) {
                idx = Evidence.EtxAppendCp(et, PcFCp(f0, f1, f2, f3, slot, i));
                if (i == 0) {
                    tstart = idx;
                }
                i += 1;
            }
            Evidence.GlSet(gl, g, Evidence.GfTstart(), tstart);
            Evidence.GlSet(gl, g, Evidence.GfTlen(), cnt);
        }
        // The advance: tx = (w0 * Tfs + Tc + Tw) * Th, or ty = w1 * Tfs + Tc + Tw.
        long adv = (long) 0;
        if (vert == 0) {
            adv = unchecked(wfx + tc);
        } else {
            adv = unchecked(Fx.FxMuldiv((long) dwv, fs, (long) 100000) + tc);
        }
        if ((code == 32) && (ncode == 1)) {
            adv = unchecked(adv + tw);
        }
        if (vert == 0) {
            PcAdvance(cx, Fx.FxMul(adv, th), (long) 0);
        } else {
            PcAdvance(cx, (long) 0, adv);
        }
        return 0;
    }
    internal static int PcShowStr(emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int s) {
        // Show the string operand s: split it into codes by the font's codespace.
        int start = PcEa(ox, s);
        int ln = PcEb(ox, s);
        int slot = emon.Port.CellsAt(cx, CSlot);
        int okfont = 0;
        int i = 0;
        int n = 1;
        int code = 0;
        int k = 0;
        int b0 = 0;
        int b1 = -1;
        int b2 = -1;
        int b3 = -1;
        if (slot >= 0) {
            if (emon.Port.CellsAt(cx, (CSlots + (slot * SlotStride)) + SStatus) == 0) {
                okfont = 1;
            }
        }
        while (i < ln) {
            b0 = emon.Port.CellsAt(ox, start + i);
            b1 = -1;
            b2 = -1;
            b3 = -1;
            if ((i + 1) < ln) {
                b1 = emon.Port.CellsAt(ox, start + (i + 1));
            }
            if ((i + 2) < ln) {
                b2 = emon.Port.CellsAt(ox, start + (i + 2));
            }
            if ((i + 3) < ln) {
                b3 = emon.Port.CellsAt(ox, start + (i + 3));
            }
            n = 1;
            if (okfont == 1) {
                n = PcFCodeLen(f0, f1, f2, f3, slot, b0, b1, b2, b3);
            }
            if (n < 1) {
                n = 1;
            }
            if (n > 4) {
                n = 4;
            }
            if ((i + n) > ln) {
                n = ln - i;
            }
            code = 0;
            k = 0;
            while (k < n) {
                if ((n == 4) && ((k == 0) && (emon.Port.CellsAt(ox, start + i) >= 128))) {
                    code = (emon.Port.CellsAt(ox, start + i) - 256) * 16777216;
                } else {
                    code = (code * 256) + emon.Port.CellsAt(ox, start + (i + k));
                }
                k += 1;
            }
            PcGlyph(cx, gl, et, f0, f1, f2, f3, code, n);
            i += n;
        }
        return 0;
    }
    internal static int PcShowArr(emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, int s) {
        // TJ: strings and adjustments. An adjustment n moves the position by
        // -n/1000 of the font size (along x, scaled by Th; along y in vertical mode).
        int cnt = PcEa(ox, s);
        int slot = emon.Port.CellsAt(cx, CSlot);
        long fs = Fx.FxGet(cx, CCur + GFs);
        long th = Fx.FxGet(cx, CCur + GTh);
        int vert = 0;
        int j = s + 1;
        int k = 0;
        long delta = (long) 0;
        if (slot >= 0) {
            vert = emon.Port.CellsAt(cx, (CSlots + (slot * SlotStride)) + SVert);
        }
        while (j < ((s + 1) + cnt)) {
            k = PcKind(ox, j);
            if (k == KStr) {
                PcShowStr(cx, ox, gl, et, f0, f1, f2, f3, j);
            }
            if (k == KNum) {
                delta = ((long) 0) - Fx.FxMuldiv(Fx.FxMul(Fx.FxJoin(PcEa(ox, j), PcEb(ox, j)), fs), (long) 1, (long) 1000);
                if (vert == 0) {
                    PcAdvance(cx, Fx.FxMul(delta, th), (long) 0);
                } else {
                    PcAdvance(cx, (long) 0, delta);
                }
            }
            j += PcEsize(ox, j);
        }
        return 0;
    }
    internal static readonly int[] PcPdfdocTab = new int[] {
        728, 711, 710, 729, 733, 731, 730, 732, 8226, 8224, 8225, 8230, 8212, 8211, 402, 8260,
        8249, 8250, 8722, 8240, 8222, 8220, 8221, 8216, 8217, 8218, 8482, 64257, 64258, 321, 338, 352,
        376, 381, 305, 322, 339, 353, 382, 65533, 8364
    };
    internal static int PcPdfdoc(int c) {
        // PDFDocEncoding (Annex D.2) to Unicode: Latin-1 except 0x18-0x1F, 0x80-0xA0.
        if ((c >= 24) && (c <= 31)) {
            return PcPdfdocTab[c - 24];
        }
        if ((c >= 128) && (c <= 160)) {
            return PcPdfdocTab[8 + (c - 128)];
        }
        return c;
    }
    internal static int PcPushBytes(emon.Port.Cells et, emon.Port.Cells ox, int start, int ln) {
        // A name's bytes as code points (Latin-1), into the evidence text. Answers
        // the index of the first.
        int at = emon.Port.CellsLen(et);
        int k = 0;
        while (k < ln) {
            Evidence.EtxAppendCp(et, emon.Port.CellsAt(ox, start + k));
            k += 1;
        }
        return at;
    }
    internal static int PcPushEntry(emon.Port.Cells et, emon.Port.Cells ox, int i) {
        // The bytes of name operand i into the evidence text; the index of the first.
        int s = PcEa(ox, i);
        int ln = PcEb(ox, i);
        return PcPushBytes(et, ox, s, ln);
    }
    internal static int PcPushUtf16(emon.Port.Cells et, emon.Port.Cells ox, int start, int ln, int little) {
        // UTF-16 text from ox[start, start+ln) (after the byte order mark), into
        // the evidence text: surrogate pairs joined, a lone surrogate U+FFFD, and
        // the language escapes of PDF 2.0 (U+001B ... U+001B) dropped.
        int k = 0;
        int u = 0;
        int u2 = 0;
        int skip = 0;
        while ((k + 1) < ln) {
            if (little == 1) {
                u = emon.Port.CellsAt(ox, start + k) + (emon.Port.CellsAt(ox, start + (k + 1)) * 256);
            } else {
                u = (emon.Port.CellsAt(ox, start + k) * 256) + emon.Port.CellsAt(ox, start + (k + 1));
            }
            k += 2;
            if ((u >= 55296) && (u <= 56319) && ((k + 1) < ln)) {
                if (little == 1) {
                    u2 = emon.Port.CellsAt(ox, start + k) + (emon.Port.CellsAt(ox, start + (k + 1)) * 256);
                } else {
                    u2 = (emon.Port.CellsAt(ox, start + k) * 256) + emon.Port.CellsAt(ox, start + (k + 1));
                }
                if ((u2 >= 56320) && (u2 <= 57343)) {
                    u = 65536 + (((u - 55296) * 1024) + (u2 - 56320));
                    k += 2;
                }
            }
            if (u == 27) {
                skip = 1 - skip;
            } else if (skip == 0) {
                Evidence.EtxAppendCp(et, u);
            }
        }
        return 0;
    }
    internal static int PcPushUtf8(emon.Port.Cells et, emon.Port.Cells ox, int start, int ln) {
        int k = 0;
        int c = 0;
        int need = 0;
        int v = 0;
        int j = 0;
        int ok = 0;
        while (k < ln) {
            c = emon.Port.CellsAt(ox, start + k);
            k += 1;
            need = 0;
            v = c;
            if (c >= 240) {
                need = 3;
                v = c - 240;
            } else if (c >= 224) {
                need = 2;
                v = c - 224;
            } else if (c >= 192) {
                need = 1;
                v = c - 192;
            }
            ok = 1;
            if ((c >= 128) && (c < 192)) {
                ok = 0;
            }
            if (c > 247) {
                ok = 0;
            }
            j = 0;
            while ((ok == 1) && (j < need)) {
                if ((k < ln) && ((emon.Port.CellsAt(ox, start + k) >= 128) && (emon.Port.CellsAt(ox, start + k) < 192))) {
                    v = (v * 64) + (emon.Port.CellsAt(ox, start + k) - 128);
                    k += 1;
                } else {
                    ok = 0;
                }
                j += 1;
            }
            if (ok == 1) {
                Evidence.EtxAppendCp(et, v);
            } else {
                Evidence.EtxAppendCp(et, 65533);
            }
        }
        return 0;
    }
    internal static int PcPushText(emon.Port.Cells et, emon.Port.Cells ox, int start, int ln) {
        // A PDF text string (UTF-16BE or LE with a byte order mark, UTF-8 with its
        // BOM, else PDFDocEncoding) into the evidence text. Answers the first index.
        int at = emon.Port.CellsLen(et);
        int k = 0;
        if ((ln >= 2) && ((emon.Port.CellsAt(ox, start) == 254) && (emon.Port.CellsAt(ox, start + 1) == 255))) {
            PcPushUtf16(et, ox, start + 2, ln - 2, 0);
            return at;
        }
        if ((ln >= 2) && ((emon.Port.CellsAt(ox, start) == 255) && (emon.Port.CellsAt(ox, start + 1) == 254))) {
            PcPushUtf16(et, ox, start + 2, ln - 2, 1);
            return at;
        }
        if ((ln >= 3) && ((emon.Port.CellsAt(ox, start) == 239) && ((emon.Port.CellsAt(ox, start + 1) == 187) && (emon.Port.CellsAt(ox, start + 2) == 191)))) {
            PcPushUtf8(et, ox, start + 3, ln - 3);
            return at;
        }
        while (k < ln) {
            Evidence.EtxAppendCp(et, PcPdfdoc(emon.Port.CellsAt(ox, start + k)));
            k += 1;
        }
        return at;
    }
    internal static long PcArFx64(emon.Port.Cells ar, int h) {
        int kind = Pdflex.PlKindOf(ar, h);
        if (kind == 2) {
            return Fx.FxOfInt(Pdflex.PlIntValue(ar, h));
        }
        if (kind == 3) {
            return Fx.FxOfReal(Pdflex.PlIntValue(ar, h), Pdflex.PlRefGen(ar, h));
        }
        return (long) 0;
    }
    internal static int PcIngestProps(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, int dict) {
        // Copy the pairs of a /Properties dictionary that marked content reads
        // into the operand entries as a dictionary entry, so one reader serves an
        // inline property list and a named one. Answers the entry's index.
        int d = PcOxPush(cx, ox, KDict, 0, 0, 0);
        int k = Pdflex.PlFirst(ar, dict);
        int v = 0;
        int vr = 0;
        int want = 0;
        int kind = 0;
        int at = 0;
        int j = 0;
        int ln = 0;
        long fxv = (long) 0;
        if (d < 0) {
            return -1;
        }
        while (k != 0) {
            v = Pdflex.PlNext(ar, k);
            want = 0;
            if (Pdflex.PlKindOf(ar, k) == 4) {
                if ((Pdflex.PlNameIs(ar, k, Pdfnames.PnMcid()) == 1) || ((Pdflex.PlNameIs(ar, k, Pdfnames.PnActualText()) == 1) || ((Pdflex.PlNameIs(ar, k, Pdfnames.PnAlt()) == 1) || ((Pdflex.PlNameIs(ar, k, Pdfnames.PnE()) == 1) || ((Pdflex.PlNameIs(ar, k, Pdfnames.PnLang()) == 1) || ((Pdflex.PlNameIs(ar, k, Pdfnames.PnType()) == 1) || (Pdflex.PlNameIs(ar, k, Pdfnames.PnSubtype()) == 1))))))) {
                    want = 1;
                }
            }
            if ((want == 1) && (v != 0)) {
                vr = Pdfdoc.PdResolve(src, ar, dc, a, b, st, v);
                kind = 0;
                if (vr != 0) {
                    kind = Pdflex.PlKindOf(ar, vr);
                }
                if ((kind == 2) || (kind == 3)) {
                    fxv = PcArFx64(ar, vr);
                    // The key, then the number.
                    ln = Pdflex.PlNameLen(ar, k);
                    at = emon.Port.CellsLen(ox);
                    j = 0;
                    while (j < ln) {
                        emon.Port.CellsPush(ox, Pdflex.PlNameByte(ar, k, j));
                        j += 1;
                    }
                    PcOxPush(cx, ox, KName, at, ln, 0);
                    PcOxPush(cx, ox, KNum, Fx.FxHi(fxv), Fx.FxLo(fxv), 1);
                }
                if ((kind == 4) || (kind == 5)) {
                    ln = Pdflex.PlNameLen(ar, k);
                    at = emon.Port.CellsLen(ox);
                    j = 0;
                    while (j < ln) {
                        emon.Port.CellsPush(ox, Pdflex.PlNameByte(ar, k, j));
                        j += 1;
                    }
                    PcOxPush(cx, ox, KName, at, ln, 0);
                    ln = Pdflex.PlStrLen(ar, vr);
                    at = emon.Port.CellsLen(ox);
                    j = 0;
                    if (kind == 4) {
                        while (j < ln) {
                            emon.Port.CellsPush(ox, Pdflex.PlNameByte(ar, vr, j));
                            j += 1;
                        }
                    } else {
                        while (j < ln) {
                            emon.Port.CellsPush(ox, Pdflex.PlStrByte(ar, vr, j));
                            j += 1;
                        }
                    }
                    if (kind == 4) {
                        PcOxPush(cx, ox, KName, at, ln, 0);
                    } else {
                        PcOxPush(cx, ox, KStr, at, ln, 0);
                    }
                }
            }
            if (v == 0) {
                k = 0;
            } else {
                k = Pdflex.PlNext(ar, v);
            }
        }
        emon.Port.CellsSet(ox, (d * 4) + 1, (emon.Port.CellsAt(cx, COxn) - d) - 1);
        return d;
    }
    internal static int PcReadProps(emon.Port.Cells et, emon.Port.Cells sp, emon.Port.Cells ox, int span, int d) {
        // Fill the span's fields from the dictionary entry d of the operands: MCID,
        // Type, Subtype, ActualText, Alt, E, Lang. Answers a code for the artifact's
        // class: 1 watermark, 2 background, 3 pagination, 4 layout, 5 another
        // named type or subtype, 0 none.
        int end = (d + 1) + PcEa(ox, d);
        int j = d + 1;
        int v = 0;
        int ks = 0;
        int kl = 0;
        int vs = 0;
        int vl = 0;
        int vk = 0;
        int at = 0;
        int cls = 0;
        while (j < end) {
            v = j + 1;
            if ((PcKind(ox, j) == KName) && (v < end)) {
                ks = PcEa(ox, j);
                kl = PcEb(ox, j);
                vk = PcKind(ox, v);
                vs = PcEa(ox, v);
                vl = PcEb(ox, v);
                if ((PcNameEq(ox, ks, kl, Pdfnames.PnMcid()) == 1) && (vk == KNum)) {
                    Evidence.SpSet(sp, span, Evidence.SfMcid(), Fx.FxRound(Fx.FxJoin(vs, vl)));
                }
                if ((PcNameEq(ox, ks, kl, Pdfnames.PnType()) == 1) && (vk == KName)) {
                    at = PcPushBytes(et, ox, vs, vl);
                    Evidence.SpSet(sp, span, Evidence.SfType(), at);
                    Evidence.SpSet(sp, span, Evidence.SfTypelen(), vl);
                    if (PcNameEq(ox, vs, vl, Pdfnames.PnPagination()) == 1) {
                        if (cls == 0) {
                            cls = 3;
                        }
                    }
                    if (PcNameEq(ox, vs, vl, Pdfnames.PnLayout()) == 1) {
                        if (cls == 0) {
                            cls = 4;
                        }
                    }
                    if (PcNameEq(ox, vs, vl, Pdfnames.PnBackground()) == 1) {
                        if (cls != 1) {
                            cls = 2;
                        }
                    }
                    if (cls == 0) {
                        cls = 5;
                    }
                }
                if ((PcNameEq(ox, ks, kl, Pdfnames.PnSubtype()) == 1) && (vk == KName)) {
                    at = PcPushBytes(et, ox, vs, vl);
                    Evidence.SpSet(sp, span, Evidence.SfSubtype(), at);
                    Evidence.SpSet(sp, span, Evidence.SfSubtypelen(), vl);
                    if (PcNameEq(ox, vs, vl, Pdfnames.PnWatermark()) == 1) {
                        cls = 1;
                    }
                    if (PcNameEq(ox, vs, vl, Pdfnames.PnBackground()) == 1) {
                        if (cls != 1) {
                            cls = 2;
                        }
                    }
                    if ((PcNameEq(ox, vs, vl, Pdfnames.PnHeader()) == 1) || (PcNameEq(ox, vs, vl, Pdfnames.PnFooter()) == 1)) {
                        if ((cls == 0) || (cls == 5)) {
                            cls = 3;
                        }
                    }
                    if (cls == 0) {
                        cls = 5;
                    }
                }
                if ((vk == KStr) || (vk == KName)) {
                    if (PcNameEq(ox, ks, kl, Pdfnames.PnActualText()) == 1) {
                        at = PcPushText(et, ox, vs, vl);
                        Evidence.SpSet(sp, span, Evidence.SfActual(), at);
                        Evidence.SpSet(sp, span, Evidence.SfActuallen(), emon.Port.CellsLen(et) - at);
                    }
                    if (PcNameEq(ox, ks, kl, Pdfnames.PnAlt()) == 1) {
                        at = PcPushText(et, ox, vs, vl);
                        Evidence.SpSet(sp, span, Evidence.SfAlt(), at);
                        Evidence.SpSet(sp, span, Evidence.SfAltlen(), emon.Port.CellsLen(et) - at);
                    }
                    if (PcNameEq(ox, ks, kl, Pdfnames.PnE()) == 1) {
                        at = PcPushText(et, ox, vs, vl);
                        Evidence.SpSet(sp, span, Evidence.SfExp(), at);
                        Evidence.SpSet(sp, span, Evidence.SfExplen(), emon.Port.CellsLen(et) - at);
                    }
                    if (PcNameEq(ox, ks, kl, Pdfnames.PnLang()) == 1) {
                        at = PcPushText(et, ox, vs, vl);
                        Evidence.SpSet(sp, span, Evidence.SfLang(), at);
                        Evidence.SpSet(sp, span, Evidence.SfLanglen(), emon.Port.CellsLen(et) - at);
                    }
                }
                j = v + PcEsize(ox, v);
            } else {
                j += PcEsize(ox, j);
            }
        }
        return cls;
    }
    internal static int PcMcRecompute(emon.Port.Cells cx, emon.Port.Cells sp) {
        // The innermost MCID and artifact class in force: walk the open spans.
        int t = emon.Port.CellsAt(cx, CMctop);
        int mcid = -1;
        int art = 0;
        int guard = 0;
        int m = 0;
        while ((t >= 0) && (guard <= MaxMc)) {
            if (mcid < 0) {
                m = Evidence.SpGet(sp, t, Evidence.SfMcid());
                if (m >= 0) {
                    mcid = m;
                }
            }
            if (art == 0) {
                art = Evidence.SpGet(sp, t, Evidence.SfArtifact());
            }
            t = Evidence.SpGet(sp, t, Evidence.SfParent());
            guard += 1;
        }
        emon.Port.CellsSet(cx, CCurmcid, mcid);
        emon.Port.CellsSet(cx, CCurart, art);
        return 0;
    }
    internal static int PcMcPop(emon.Port.Cells cx, emon.Port.Cells sp, emon.Port.Cells gl, int unterminated) {
        // Close the innermost open span: its glyphs are those shown since it opened.
        int t = emon.Port.CellsAt(cx, CMctop);
        if (t < 0) {
            return 0;
        }
        int g = Evidence.GlCount(gl);
        int gf = Evidence.SpGet(sp, t, Evidence.SfGfirst());
        int par = Evidence.SpGet(sp, t, Evidence.SfParent());
        Evidence.SpSet(sp, t, Evidence.SfGcount(), g - gf);
        if (unterminated == 1) {
            int fl = Evidence.SpGet(sp, t, Evidence.SfFlags());
            Evidence.SpSet(sp, t, Evidence.SfFlags(), fl | Evidence.McUnterminated());
        }
        emon.Port.CellsSet(cx, CMctop, par);
        emon.Port.CellsSet(cx, CMcdepth, emon.Port.CellsAt(cx, CMcdepth) - 1);
        PcMcRecompute(cx, sp);
        return 0;
    }
    internal static int PcMcBegin(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells sp, int n, int props) {
        // BMC / BDC: open a span with the tag of operand 0 and, for BDC, the
        // properties of operand 1 (an inline dictionary, or a name in /Properties).
        int depth = emon.Port.CellsAt(cx, CMcdepth);
        int tstart = 0;
        int tlen = 0;
        int span = 0;
        int d = -1;
        int cls = 0;
        int raw = 0;
        int dh = 0;
        int isart = 0;
        int flags = 0;
        if (depth >= MaxMc) {
            emon.Port.CellsSet(cx, CMcover, emon.Port.CellsAt(cx, CMcover) + 1);
            PcWarnSet(cx, WMc);
            return 0;
        }
        tstart = emon.Port.CellsLen(et);
        if ((n >= 1) && (PcKind(ox, 0) == KName)) {
            tstart = PcPushEntry(et, ox, 0);
            tlen = PcEb(ox, 0);
            if (PcEntryNameIs(ox, 0, Pdfnames.PnArtifact()) == 1) {
                isart = 1;
            }
        }
        span = Evidence.SpNew(sp, emon.Port.CellsAt(cx, CPage), tstart, tlen, emon.Port.CellsAt(cx, CMctop), Evidence.GlCount(gl));
        Evidence.SpSet(sp, span, Evidence.SfStm(), emon.Port.CellsAt(cx, CStm));
        if (isart == 1) {
            Evidence.SpSet(sp, span, Evidence.SfArtifact(), Evidence.ArOther());
        }
        if ((props == 1) && (n >= 2)) {
            if (PcKind(ox, 1) == KDict) {
                d = 1;
                flags = Evidence.McInline();
            }
            if (PcKind(ox, 1) == KName) {
                raw = PcResEntry(src, ar, dc, a, b, st, cx, ox, Pdfnames.PnProperties(), 1);
                if (raw != 0) {
                    dh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, raw);
                }
                if (Pdfsrc.PsMissed(src)) {
                    emon.Port.CellsSet(cx, CAbort, 1);
                }
                if ((dh != 0) && (Pdflex.PlKindOf(ar, dh) == 7)) {
                    d = PcIngestProps(src, ar, dc, a, b, st, cx, ox, dh);
                    flags = Evidence.McResource();
                } else {
                    flags = Evidence.McUnresolved();
                    PcWarnSet(cx, WProps);
                }
            }
            Evidence.SpSet(sp, span, Evidence.SfFlags(), flags);
            if (d >= 0) {
                cls = PcReadProps(et, sp, ox, span, d);
                if (isart == 1) {
                    if (cls == 1) {
                        Evidence.SpSet(sp, span, Evidence.SfArtifact(), Evidence.ArWatermark());
                    }
                    if (cls == 2) {
                        Evidence.SpSet(sp, span, Evidence.SfArtifact(), Evidence.ArBackground());
                    }
                    if (cls == 3) {
                        Evidence.SpSet(sp, span, Evidence.SfArtifact(), Evidence.ArPagination());
                    }
                    if (cls == 4) {
                        Evidence.SpSet(sp, span, Evidence.SfArtifact(), Evidence.ArLayout());
                    }
                }
            }
        }
        emon.Port.CellsSet(cx, CMctop, span);
        emon.Port.CellsSet(cx, CMcdepth, depth + 1);
        PcMcRecompute(cx, sp);
        return 0;
    }
    internal static int PcMcEnd(emon.Port.Cells cx, emon.Port.Cells sp, emon.Port.Cells gl) {
        // EMC: close the innermost span this stream opened; a BDC that was too deep
        // to record is balanced first; an EMC with nothing to close is ignored.
        int over = emon.Port.CellsAt(cx, CMcover);
        if (over > 0) {
            emon.Port.CellsSet(cx, CMcover, over - 1);
            return 0;
        }
        if (emon.Port.CellsAt(cx, CMcdepth) <= emon.Port.CellsAt(cx, CMcbase)) {
            PcWarnSet(cx, WMc);
            return 0;
        }
        return PcMcPop(cx, sp, gl, 0);
    }
    internal static int PcSkipInline(emon.Port.Cells cx, emon.Port.Cells cs) {
        // BI: skip to the end of the inline image: find `ID` and its one white
        // space, then the first `EI` that stands alone (white space before and white
        // space or the end after). Binary data rarely contains one; if it does the
        // rest is read as operators and skipped as unknown ones.
        int end = emon.Port.CellsAt(cx, CEnd);
        int p = emon.Port.CellsAt(cx, CPos);
        int found = 0;
        while (((p + 2) < end) && (found == 0)) {
            if ((PcWs(emon.Port.CellsAt(cs, p)) == 1) && ((emon.Port.CellsAt(cs, p + 1) == 73) && ((emon.Port.CellsAt(cs, p + 2) == 68) && (((p + 3) >= end) || (PcWs(emon.Port.CellsAt(cs, p + 3)) == 1))))) {
                found = 1;
                p += 4;
            } else {
                p += 1;
            }
        }
        if (found == 0) {
            emon.Port.CellsSet(cx, CPos, end);
            return 0;
        }
        found = 0;
        while (((p + 1) < end) && (found == 0)) {
            if ((emon.Port.CellsAt(cs, p) == 69) && ((emon.Port.CellsAt(cs, p + 1) == 73) && (((p == 0) || (PcWs(emon.Port.CellsAt(cs, p - 1)) == 1)) && (((p + 2) >= end) || (PcWs(emon.Port.CellsAt(cs, p + 2)) == 1))))) {
                found = 1;
                p += 2;
            } else {
                p += 1;
            }
        }
        if (found == 0) {
            p = end;
        }
        emon.Port.CellsSet(cx, CPos, p);
        return 0;
    }
    internal static int PcAppendStream(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells @out, emon.Port.Cells cs, int sh) {
        // Decode stream sh and append its bytes (and a line feed) to `cs`. Answers
        // the filter chain's status (0 ok), or -1 when the source missed.
        int status = Pdfdoc.PdStreamData(src, ar, dc, a, b, st, sh, @out);
        int n = emon.Port.CellsLen(@out);
        int i = 0;
        if (Pdfsrc.PsMissed(src)) {
            emon.Port.CellsSet(cx, CAbort, 1);
            return -1;
        }
        if (status != 0) {
            PcWarnSet(cx, WStream);
            emon.Port.CellsSet(cx, CSstat, status);
        }
        while (i < n) {
            emon.Port.CellsPush(cs, emon.Port.CellsAt(@out, i));
            i += 1;
        }
        emon.Port.CellsPush(cs, 10);
        return status;
    }
    internal static int PcDo(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells sp, int n) {
        // Do: run the Form XObject named by operand 0. Images and everything that is
        // not a form are skipped. The form's /Matrix is concatenated to the CTM, its
        // /Resources replace the current ones (else they are inherited), and it runs
        // inside its own `q`/`Q`.
        if (n < 1) {
            return 0;
        }
        if (PcKind(ox, 0) != KName) {
            return 0;
        }
        int raw = PcResEntry(src, ar, dc, a, b, st, cx, ox, Pdfnames.PnXObject(), 0);
        int objnum = 0;
        int xh = 0;
        int sub = 0;
        int fd = 0;
        int i = 0;
        int mat = 0;
        int el = 0;
        int got = 0;
        int res = 0;
        int oldres = 0;
        int oldstm = 0;
        int start = 0;
        int endcs = 0;
        int status = 0;
        if (Pdfsrc.PsMissed(src)) {
            emon.Port.CellsSet(cx, CAbort, 1);
            return 0;
        }
        if (raw == 0) {
            PcWarnSet(cx, WForm);
            return 0;
        }
        if (Pdflex.PlKindOf(ar, raw) == 9) {
            objnum = Pdflex.PlIntValue(ar, raw);
        }
        xh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, raw);
        if (Pdfsrc.PsMissed(src)) {
            emon.Port.CellsSet(cx, CAbort, 1);
            return 0;
        }
        if (xh == 0) {
            PcWarnSet(cx, WForm);
            return 0;
        }
        if (Pdflex.PlKindOf(ar, xh) != 8) {
            return 0;
        }
        sub = Pdfdoc.PdDget(src, ar, dc, a, b, st, xh, Pdfnames.PnSubtype());
        if (Pdfsrc.PsMissed(src)) {
            emon.Port.CellsSet(cx, CAbort, 1);
            return 0;
        }
        if (sub == 0) {
            return 0;
        }
        if (Pdflex.PlNameIs(ar, sub, Pdfnames.PnForm()) == 0) {
            return 0;
        }
        // Depth and cycles: a form deeper than FORM_DEPTH, or already running, is skipped.
        fd = emon.Port.CellsAt(cx, CFdepth);
        if ((fd >= MaxForms) || (fd >= emon.Port.CellsAt(cx, CFlim))) {
            PcWarnSet(cx, WDepth);
            return 0;
        }
        if (objnum != 0) {
            while (i < fd) {
                if (emon.Port.CellsAt(cx, CFstack + i) == objnum) {
                    PcWarnSet(cx, WDepth);
                    return 0;
                }
                i += 1;
            }
        }
        // Its /Matrix (six numbers, else the identity).
        Fx.MxIdent(cx, CTmp);
        mat = Pdfdoc.PdDget(src, ar, dc, a, b, st, xh, Pdfnames.PnMatrix());
        if ((mat != 0) && (Pdflex.PlKindOf(ar, mat) == 6)) {
            el = Pdflex.PlFirst(ar, mat);
            got = 0;
            while ((el != 0) && (got < 6)) {
                Fx.FxPut(cx, CTmp + (got * 2), PcArFx64(ar, el));
                el = Pdflex.PlNext(ar, el);
                got += 1;
            }
            if (got < 6) {
                Fx.MxIdent(cx, CTmp);
            }
        }
        res = Pdfdoc.PdDget(src, ar, dc, a, b, st, xh, Pdfnames.PnResources());
        oldres = emon.Port.CellsAt(cx, CRes);
        oldstm = emon.Port.CellsAt(cx, CStm);
        if ((res != 0) && (Pdflex.PlKindOf(ar, res) == 7)) {
            emon.Port.CellsSet(cx, CRes, res);
        }
        start = emon.Port.CellsLen(cs);
        status = PcAppendStream(src, ar, dc, a, b, st, cx, @out, cs, xh);
        if (status == -1) {
            return 0;
        }
        PcSave(cx);
        Fx.MxMul(cx, CCur + GCtm, CTmp, CCur + GCtm);
        emon.Port.CellsSet(cx, CFstack + fd, objnum);
        emon.Port.CellsSet(cx, CFdepth, fd + 1);
        emon.Port.CellsSet(cx, CStm, objnum);
        endcs = emon.Port.CellsLen(cs);
        PcRun(src, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, sp, start, endcs);
        emon.Port.CellsSet(cx, CFdepth, fd);
        emon.Port.CellsSet(cx, CStm, oldstm);
        emon.Port.CellsSet(cx, CRes, oldres);
        PcRestore(cx);
        emon.Port.CellsDrop(cs, start);
        return 0;
    }
    internal static int PcPrep(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3) {
        // Before a string is shown: the font resident, and M = Tm x CTM current.
        PcEnsureFont(src, ar, dc, a, b, st, cx, @out, f0, f1, f2, f3);
        PcUpdateM(cx);
        if (emon.Port.CellsAt(cx, CSlot) < 0) {
            PcWarnSet(cx, WText);
        }
        return 0;
    }
    internal static int PcOp(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells sp, int op, int n) {
        // Execute one operator; `ox` holds its n operands. Unknown operators do
        // nothing (their operands are dropped by the caller).
        if (op == OpSave) {
            PcSave(cx);
            return 0;
        }
        if (op == OpRestore) {
            PcRestore(cx);
            return 0;
        }
        if (op == OpCm) {
            if (n >= 6) {
                Fx.MxSet(cx, CTmp, PcNum(ox, n, 0), PcNum(ox, n, 1), PcNum(ox, n, 2), PcNum(ox, n, 3), PcNum(ox, n, 4), PcNum(ox, n, 5));
                Fx.MxMul(cx, CCur + GCtm, CTmp, CCur + GCtm);
            }
            return 0;
        }
        if (op == OpBt) {
            Fx.MxIdent(cx, CTm);
            Fx.MxIdent(cx, CTlm);
            emon.Port.CellsSet(cx, CIntext, 1);
            return 0;
        }
        if (op == OpEt) {
            emon.Port.CellsSet(cx, CIntext, 0);
            return 0;
        }
        if (op == OpTf) {
            PcTf(src, ar, dc, a, b, st, cx, ox, n);
            return 0;
        }
        if (op == OpTchar) {
            Fx.FxPut(cx, CCur + GTc, PcNum(ox, n, 0));
            return 0;
        }
        if (op == OpTword) {
            Fx.FxPut(cx, CCur + GTw, PcNum(ox, n, 0));
            return 0;
        }
        if (op == OpTscale) {
            Fx.FxPut(cx, CCur + GTh, Fx.FxMuldiv(PcNum(ox, n, 0), (long) 1, (long) 100));
            return 0;
        }
        if (op == OpTlead) {
            Fx.FxPut(cx, CCur + GTl, PcNum(ox, n, 0));
            return 0;
        }
        if (op == OpTrise) {
            Fx.FxPut(cx, CCur + GRise, PcNum(ox, n, 0));
            return 0;
        }
        if (op == OpTmode) {
            emon.Port.CellsSet(cx, CCur + GMode, Fx.FxRound(PcNum(ox, n, 0)));
            return 0;
        }
        if (op == OpTd) {
            PcTd(cx, PcNum(ox, n, 0), PcNum(ox, n, 1));
            return 0;
        }
        if (op == OpTdl) {
            Fx.FxPut(cx, CCur + GTl, ((long) 0) - PcNum(ox, n, 1));
            PcTd(cx, PcNum(ox, n, 0), PcNum(ox, n, 1));
            return 0;
        }
        if (op == OpTm) {
            if (n >= 6) {
                PcSetTm(cx, PcNum(ox, n, 0), PcNum(ox, n, 1), PcNum(ox, n, 2), PcNum(ox, n, 3), PcNum(ox, n, 4), PcNum(ox, n, 5));
            }
            return 0;
        }
        if (op == OpTstar) {
            PcNextLine(cx);
            return 0;
        }
        if (op == OpShow) {
            if ((n >= 1) && (PcKind(ox, 0) == KStr)) {
                PcPrep(src, ar, dc, a, b, st, cx, @out, f0, f1, f2, f3);
                PcShowStr(cx, ox, gl, et, f0, f1, f2, f3, 0);
            }
            return 0;
        }
        if (op == OpShowarr) {
            if ((n >= 1) && (PcKind(ox, 0) == KArr)) {
                PcPrep(src, ar, dc, a, b, st, cx, @out, f0, f1, f2, f3);
                PcShowArr(cx, ox, gl, et, f0, f1, f2, f3, 0);
            }
            return 0;
        }
        if (op == OpQuote) {
            if ((n >= 1) && (PcKind(ox, 0) == KStr)) {
                PcNextLine(cx);
                PcPrep(src, ar, dc, a, b, st, cx, @out, f0, f1, f2, f3);
                PcShowStr(cx, ox, gl, et, f0, f1, f2, f3, 0);
            }
            return 0;
        }
        if (op == OpDquote) {
            if ((n >= 3) && (PcKind(ox, 2) == KStr)) {
                Fx.FxPut(cx, CCur + GTw, PcNum(ox, n, 0));
                Fx.FxPut(cx, CCur + GTc, PcNum(ox, n, 1));
                PcNextLine(cx);
                PcPrep(src, ar, dc, a, b, st, cx, @out, f0, f1, f2, f3);
                PcShowStr(cx, ox, gl, et, f0, f1, f2, f3, 2);
            }
            return 0;
        }
        if (op == OpDo) {
            PcDo(src, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, sp, n);
            return 0;
        }
        if (op == OpBdc) {
            PcMcBegin(src, ar, dc, a, b, st, cx, ox, gl, et, sp, n, 1);
            return 0;
        }
        if (op == OpBmc) {
            PcMcBegin(src, ar, dc, a, b, st, cx, ox, gl, et, sp, n, 0);
            return 0;
        }
        if (op == OpEmc) {
            PcMcEnd(cx, sp, gl);
            return 0;
        }
        if (op == OpBi) {
            PcSkipInline(cx, cs);
            return 0;
        }
        if ((op == OpGray) || ((op == OpRgb) || ((op == OpCmyk) || ((op == OpSc) || (op == OpScn))))) {
            PcSetColor(cx, ox, n);
            return 0;
        }
        if (op == OpCs) {
            emon.Port.CellsSet(cx, CCur + GColor, 0);
            if ((n >= 1) && (PcKind(ox, 0) == KName)) {
                emon.Port.CellsSet(cx, CCur + GFam, 0);
                if (PcEntryNameIs(ox, 0, Pdfnames.PnDeviceGray()) == 1) {
                    emon.Port.CellsSet(cx, CCur + GFam, 1);
                }
                if (PcEntryNameIs(ox, 0, Pdfnames.PnDeviceRgb()) == 1) {
                    emon.Port.CellsSet(cx, CCur + GFam, 2);
                }
                if (PcEntryNameIs(ox, 0, Pdfnames.PnDeviceCmyk()) == 1) {
                    emon.Port.CellsSet(cx, CCur + GFam, 3);
                }
            }
            return 0;
        }
        if (op == OpGs) {
            if ((n >= 1) && (PcKind(ox, 0) == KName)) {
                int raw = PcResEntry(src, ar, dc, a, b, st, cx, ox, Pdfnames.PnExtGState(), 0);
                if (raw != 0) {
                    int gd = Pdfdoc.PdResolve(src, ar, dc, a, b, st, raw);
                    if (gd != 0) {
                        int cav = Pdfdoc.PdDget(src, ar, dc, a, b, st, gd, Pdfnames.PnCa());
                        if (cav != 0) {
                            int al = Fx.FxRound(Fx.FxMul(PcArFx64(ar, cav), Fx.FxOfInt(1000)));
                            if (al < 0) {
                                emon.Port.CellsSet(cx, CCur + GAlpha, 0);
                            } else if (al > 1000) {
                                emon.Port.CellsSet(cx, CCur + GAlpha, 1000);
                            } else {
                                emon.Port.CellsSet(cx, CCur + GAlpha, al);
                            }
                        }
                    }
                }
                if (Pdfsrc.PsMissed(src)) {
                    emon.Port.CellsSet(cx, CAbort, 1);
                }
            }
            return 0;
        }
        return 0;
    }
    internal static int PcRun(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells sp, int start, int end) {
        // Run the content bytes cs[start, end): read operands, then execute each
        // operator. The caller's lexer position, graphics-state floor and marked-
        // content floor are kept and restored, so a form can run inside an operator.
        int oldpos = emon.Port.CellsAt(cx, CPos);
        int oldend = emon.Port.CellsAt(cx, CEnd);
        int oldgs = emon.Port.CellsAt(cx, CGsbase);
        int oldmcb = emon.Port.CellsAt(cx, CMcbase);
        int oldover = emon.Port.CellsAt(cx, CMcover);
        int oldtop = emon.Port.CellsAt(cx, CMctop);
        int r = 1;
        int opc = 0;
        int nop = 0;
        int ops = 0;
        emon.Port.CellsSet(cx, CPos, start);
        emon.Port.CellsSet(cx, CEnd, end);
        emon.Port.CellsSet(cx, CGsbase, emon.Port.CellsAt(cx, CDepth));
        emon.Port.CellsSet(cx, CMcbase, emon.Port.CellsAt(cx, CMcdepth));
        emon.Port.CellsSet(cx, CMcover, 0);
        PcOxClear(cx, ox);
        while ((r != 0) && (emon.Port.CellsAt(cx, CAbort) == 0)) {
            r = PcLex(cx, ox, cs);
            if (r == 2) {
                ops = emon.Port.CellsAt(cx, COps) + 1;
                emon.Port.CellsSet(cx, COps, ops);
                if (ops > emon.Port.CellsAt(cx, COplim)) {
                    emon.Port.LimitBreach(5, ops);
                }
                opc = emon.Port.CellsAt(cx, COp);
                nop = emon.Port.CellsAt(cx, COxn);
                PcOp(src, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, sp, opc, nop);
                PcOxClear(cx, ox);
            }
        }
        // What the stream left open: spans, graphics states.
        while (emon.Port.CellsAt(cx, CMcdepth) > emon.Port.CellsAt(cx, CMcbase)) {
            PcWarnSet(cx, WMc);
            PcMcPop(cx, sp, gl, 1);
        }
        while (emon.Port.CellsAt(cx, CDepth) > emon.Port.CellsAt(cx, CGsbase)) {
            emon.Port.CellsSet(cx, CDepth, emon.Port.CellsAt(cx, CDepth) - 1);
        }
        emon.Port.CellsSet(cx, CMctop, oldtop);
        PcMcRecompute(cx, sp);
        emon.Port.CellsSet(cx, CMcover, oldover);
        emon.Port.CellsSet(cx, CMcbase, oldmcb);
        emon.Port.CellsSet(cx, CGsbase, oldgs);
        emon.Port.CellsSet(cx, CPos, oldpos);
        emon.Port.CellsSet(cx, CEnd, oldend);
        return 0;
    }
    internal const int WordGapPm = 160;
    internal const int WordBackPm = 400;
    internal const int OffsetPm = 450;
    internal const int LineBackPm = 600;
    internal const int LineGapPm = 2000;
    internal static int PcAxis(int rot) {
        // The writing axis a rotation is within three degrees of, else -1 (a glyph run
        // at another angle is measured along its own direction, `pc-rot-gap`).
        int a = ((rot + 4500) / 9000) % 4;
        int d = rot - (a * 9000);
        if (d < 0) {
            d = 0 - d;
        }
        if (d > 18000) {
            d = 36000 - d;
        }
        if (d <= 300) {
            return a;
        }
        return -1;
    }
    internal static int PcOffset(emon.Port.Cells gl, int j, int axis) {
        // Where glyph j's baseline is across its writing axis, in centipoints.
        if (axis == 1) {
            return Evidence.GlGet(gl, j, Evidence.GfX1());
        }
        if (axis == 3) {
            return Evidence.GlGet(gl, j, Evidence.GfX0());
        }
        return Evidence.GlGet(gl, j, Evidence.GfBaseline());
    }
    internal static int PcGap(emon.Port.Cells gl, int p, int g, int axis) {
        // The space along the axis between glyph p and the glyph g after it
        // (negative when they overlap or g is before p).
        if (axis == 0) {
            return Evidence.GlGet(gl, g, Evidence.GfX0()) - Evidence.GlGet(gl, p, Evidence.GfX1());
        }
        if (axis == 2) {
            return Evidence.GlGet(gl, p, Evidence.GfX0()) - Evidence.GlGet(gl, g, Evidence.GfX1());
        }
        if (axis == 1) {
            return Evidence.GlGet(gl, p, Evidence.GfY0()) - Evidence.GlGet(gl, g, Evidence.GfY1());
        }
        return Evidence.GlGet(gl, g, Evidence.GfY0()) - Evidence.GlGet(gl, p, Evidence.GfY1());
    }
    internal static int PcRotGap(emon.Port.Cells gl, int p, int g, int size) {
        // For text at an arbitrary angle: the distance between glyph p's centre and
        // glyph g's, along the writing direction, less 60 percent of the size (the
        // two half-advances of adjacent letters), so it reads as `pc-gap` does.
        int rot = Evidence.GlGet(gl, p, Evidence.GfRot());
        long ux = Fx.FxCos(rot);
        long uy = ((long) 0) - Fx.FxSin(rot);
        int dx2 = (Evidence.GlGet(gl, g, Evidence.GfX0()) + Evidence.GlGet(gl, g, Evidence.GfX1())) - (Evidence.GlGet(gl, p, Evidence.GfX0()) + Evidence.GlGet(gl, p, Evidence.GfX1()));
        int dy2 = (Evidence.GlGet(gl, g, Evidence.GfY0()) + Evidence.GlGet(gl, g, Evidence.GfY1())) - (Evidence.GlGet(gl, p, Evidence.GfY0()) + Evidence.GlGet(gl, p, Evidence.GfY1()));
        long al2 = unchecked(Fx.FxMul(Fx.FxOfInt(dx2), ux) + Fx.FxMul(Fx.FxOfInt(dy2), uy));
        return Fx.FxRound(al2 / ((long) 2)) - ((size * 600) / 1000);
    }
    internal static int PcRotOff(emon.Port.Cells gl, int p, int g) {
        // The distance between the two glyphs' centres across the writing direction.
        int rot = Evidence.GlGet(gl, p, Evidence.GfRot());
        long sn = Fx.FxSin(rot);
        long cs = Fx.FxCos(rot);
        int dx2 = (Evidence.GlGet(gl, g, Evidence.GfX0()) + Evidence.GlGet(gl, g, Evidence.GfX1())) - (Evidence.GlGet(gl, p, Evidence.GfX0()) + Evidence.GlGet(gl, p, Evidence.GfX1()));
        int dy2 = (Evidence.GlGet(gl, g, Evidence.GfY0()) + Evidence.GlGet(gl, g, Evidence.GfY1())) - (Evidence.GlGet(gl, p, Evidence.GfY0()) + Evidence.GlGet(gl, p, Evidence.GfY1()));
        int pe = Fx.FxRound(unchecked(Fx.FxMul(Fx.FxOfInt(dx2), sn) + Fx.FxMul(Fx.FxOfInt(dy2), cs)) / ((long) 2));
        if (pe < 0) {
            return 0 - pe;
        }
        return pe;
    }
    internal static int PcPairGap(emon.Port.Cells gl, int p, int g, int axis, int size) {
        if (axis < 0) {
            return PcRotGap(gl, p, g, size);
        }
        return PcGap(gl, p, g, axis);
    }
    internal static int PcPairOff(emon.Port.Cells gl, int p, int g, int axis) {
        // How far glyph g's baseline is from glyph p's, across the writing axis.
        if (axis < 0) {
            return PcRotOff(gl, p, g);
        }
        int d = PcOffset(gl, p, axis) - PcOffset(gl, g, axis);
        if (d < 0) {
            return 0 - d;
        }
        return d;
    }
    internal static int PcSpaceCp(int cp) {
        // 1 for a code point that separates words: the spaces (U+0020, U+00A0,
        // U+1680, U+2000..200A, U+202F, U+205F, U+3000) and the tab.
        if ((cp == 32) || ((cp == 160) || ((cp == 9) || ((cp == 5760) || ((cp == 8239) || ((cp == 8287) || (cp == 12288))))))) {
            return 1;
        }
        if ((cp >= 8192) && (cp <= 8202)) {
            return 1;
        }
        return 0;
    }
    internal static int PcCl(int v) {
        // Clamp a distance to +-1,000,000 centipoints so a per-mille product fits an I32.
        if (v > 1000000) {
            return 1000000;
        }
        if (v < -1000000) {
            return -1000000;
        }
        return v;
    }
    internal static int PcRotSame(int r1, int r2) {
        // 1 when two rotations (centi-degrees) agree to half a degree.
        int d = r1 - r2;
        if (d < 0) {
            d = 0 - d;
        }
        if (d > 18000) {
            d = 36000 - d;
        }
        if (d <= 50) {
            return 1;
        }
        return 0;
    }
    internal static int PcContinues(emon.Port.Cells gl, int p, int g) {
        // 1 when glyph g continues the word glyph p is in: the same rotation, on the
        // same baseline (to 45 percent of the size: sub- and superscripts stay), and
        // the gap along the axis neither a word space nor a step back.
        int rot = Evidence.GlGet(gl, p, Evidence.GfRot());
        int axis = PcAxis(rot);
        int size = Evidence.GlGet(gl, g, Evidence.GfSize());
        int sizep = Evidence.GlGet(gl, p, Evidence.GfSize());
        int sz = size;
        int gap = 0;
        int off = 0;
        if (PcRotSame(rot, Evidence.GlGet(gl, g, Evidence.GfRot())) == 0) {
            return 0;
        }
        if (sizep > sz) {
            sz = sizep;
        }
        if (sz > 200000) {
            sz = 200000;
        }
        if (sz < (0 - 200000)) {
            sz = 0 - 200000;
        }
        off = PcCl(PcPairOff(gl, p, g, axis));
        if ((off * 1000) > (sz * OffsetPm)) {
            return 0;
        }
        gap = PcCl(PcPairGap(gl, p, g, axis, sz));
        if ((gap * 1000) > (sz * WordGapPm)) {
            return 0;
        }
        if ((gap * 1000) < (0 - (sz * WordBackPm))) {
            return 0;
        }
        return 1;
    }
    internal static int PcCls(int cp) {
        // A code point's strength for reordering right-to-left text: 1 strong right-to-left
        // (Hebrew, Arabic, Syriac, Thaana, N'Ko and their presentation forms), 2 a left-to-right
        // letter or a digit (Arabic-Indic digits are digits: they run left to right inside
        // right-to-left text), 0 neutral (punctuation, symbols, what has no value).
        if (cp < 33) {
            return 0;
        }
        if (((cp >= 48) && (cp <= 57)) || (((cp >= 1632) && (cp <= 1641)) || ((cp >= 1776) && (cp <= 1785)))) {
            return 2;
        }
        if (((cp >= 1424) && (cp <= 2303)) || (((cp >= 64285) && (cp <= 65023)) || ((cp >= 65136) && (cp <= 65279)))) {
            return 1;
        }
        if (((cp >= 65) && (cp <= 90)) || ((cp >= 97) && (cp <= 122))) {
            return 2;
        }
        if ((cp >= 192) && ((cp < 8192) && (cp != 215))) {
            return 2;
        }
        if ((cp >= 12352) && (cp < 65000)) {
            return 2;
        }
        return 0;
    }
    internal static int PcGcls(emon.Port.Cells gl, int j) {
        return PcCls(Evidence.GlGet(gl, j, Evidence.GfCp()));
    }
    internal static int PcGlyphOut(emon.Port.Cells et, emon.Port.Cells gl, int j) {
        // Append glyph j's text (every code point it stands for, or U+FFFD) to the evidence text.
        int ts = Evidence.GlGet(gl, j, Evidence.GfTstart());
        int tl = Evidence.GlGet(gl, j, Evidence.GfTlen());
        int cp = Evidence.GlGet(gl, j, Evidence.GfCp());
        int k = 0;
        int cpv = 0;
        if ((ts >= 0) && (tl > 0)) {
            while (k < tl) {
                cpv = emon.Port.CellsAt(et, ts + k);
                Evidence.EtxAppendCp(et, cpv);
                k += 1;
            }
            return 0;
        }
        if (cp >= 0) {
            Evidence.EtxAppendCp(et, cp);
        } else {
            Evidence.EtxAppendCp(et, 65533);
        }
        return 0;
    }
    internal static int PcEmitWord(emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells wd, int page, int gfst, int glst) {
        // Record glyphs [gfst, glst] as a word: the union of their boxes, their text, the
        // dominant font and size of the first, and `hidden-text` as its source when every
        // glyph is render mode 3. A right-to-left word whose glyphs run left to right on the
        // page (visual order, as Skia and most producers write them) has its TEXT written in
        // logical order: the glyphs reversed, with the runs of digits and Latin letters in it
        // turned back. The glyphs themselves stay as they were shown.
        int x0 = Evidence.GlGet(gl, gfst, Evidence.GfX0());
        int y0 = Evidence.GlGet(gl, gfst, Evidence.GfY0());
        int x1 = Evidence.GlGet(gl, gfst, Evidence.GfX1());
        int y1 = Evidence.GlGet(gl, gfst, Evidence.GfY1());
        int j = gfst;
        int tstart = -1;
        int visible = 0;
        int nr = 0;
        int nl = 0;
        int cl = 0;
        int rtlw = 0;
        int kk = 0;
        int m = 0;
        while (j <= glst) {
            if (Evidence.GlGet(gl, j, Evidence.GfX0()) < x0) {
                x0 = Evidence.GlGet(gl, j, Evidence.GfX0());
            }
            if (Evidence.GlGet(gl, j, Evidence.GfY0()) < y0) {
                y0 = Evidence.GlGet(gl, j, Evidence.GfY0());
            }
            if (Evidence.GlGet(gl, j, Evidence.GfX1()) > x1) {
                x1 = Evidence.GlGet(gl, j, Evidence.GfX1());
            }
            if (Evidence.GlGet(gl, j, Evidence.GfY1()) > y1) {
                y1 = Evidence.GlGet(gl, j, Evidence.GfY1());
            }
            if (Evidence.GlGet(gl, j, Evidence.GfMode()) != 3) {
                visible = 1;
            }
            cl = PcGcls(gl, j);
            if (cl == 1) {
                nr += 1;
            }
            if (cl == 2) {
                nl += 1;
            }
            j += 1;
        }
        if ((nr > nl) && (glst > gfst)) {
            if (PcAxis(Evidence.GlGet(gl, gfst, Evidence.GfRot())) == 0) {
                if (Evidence.GlGet(gl, glst, Evidence.GfX0()) >= Evidence.GlGet(gl, gfst, Evidence.GfX0())) {
                    rtlw = 1;
                }
            }
        }
        tstart = emon.Port.CellsLen(et);
        if (rtlw == 0) {
            j = gfst;
            while (j <= glst) {
                PcGlyphOut(et, gl, j);
                j += 1;
            }
        } else {
            j = glst;
            while (j >= gfst) {
                if (PcGcls(gl, j) == 2) {
                    kk = j;
                    while ((kk > gfst) && (PcGcls(gl, kk - 1) == 2)) {
                        kk -= 1;
                    }
                    m = kk;
                    while (m <= j) {
                        PcGlyphOut(et, gl, m);
                        m += 1;
                    }
                    j = kk - 1;
                } else {
                    PcGlyphOut(et, gl, j);
                    j -= 1;
                }
            }
        }
        int w = Evidence.WdNew(wd, page, x0, y0, x1, y1, gfst, (glst - gfst) + 1);
        Evidence.WdSet(wd, w, Evidence.WfTstart(), tstart);
        Evidence.WdSet(wd, w, Evidence.WfTlen(), emon.Port.CellsLen(et) - tstart);
        Evidence.WdSet(wd, w, Evidence.WfFont(), Evidence.GlGet(gl, gfst, Evidence.GfFont()));
        Evidence.WdSet(wd, w, Evidence.WfSize(), Evidence.GlGet(gl, gfst, Evidence.GfSize()));
        if (visible == 0) {
            Evidence.WdSet(wd, w, Evidence.WfSrc(), Model.SrHiddenText());
        }
        j = gfst;
        while (j <= glst) {
            Evidence.GlSet(gl, j, Evidence.GfWord(), w);
            j += 1;
        }
        return w;
    }
    internal static int PcSwapRows(emon.Port.Cells wd, int i, int j) {
        int k = 0;
        int u = 0;
        int v = 0;
        while (k < 16) {
            u = emon.Port.CellsAt(wd, (i * 16) + k);
            v = emon.Port.CellsAt(wd, (j * 16) + k);
            emon.Port.CellsSet(wd, (i * 16) + k, v);
            emon.Port.CellsSet(wd, (j * 16) + k, u);
            k += 1;
        }
        return 0;
    }
    internal static int PcRevRows(emon.Port.Cells wd, int a, int b) {
        int i = a;
        int j = b;
        while (i < j) {
            PcSwapRows(wd, i, j);
            i += 1;
            j -= 1;
        }
        return 0;
    }
    internal static int PcWcls(emon.Port.Cells gl, emon.Port.Cells wd, int w) {
        // 2 when the word has more left-to-right letters and digits than right-to-left letters.
        int g0 = Evidence.WdGet(wd, w, Evidence.WfGfirst());
        int gn = Evidence.WdGet(wd, w, Evidence.WfGcount());
        int j = 0;
        int nr = 0;
        int nl = 0;
        int cl = 0;
        while (j < gn) {
            cl = PcGcls(gl, g0 + j);
            if (cl == 1) {
                nr += 1;
            }
            if (cl == 2) {
                nl += 1;
            }
            j += 1;
        }
        if (nr > nl) {
            return 1;
        }
        return 2;
    }
    internal static int PcLineBidi(emon.Port.Cells gl, emon.Port.Cells wd, emon.Port.Cells ln, int lidx, int wfst, int wlst) {
        // Line lidx holds words [wfst, wlst]. When more of its glyphs are right-to-left than
        // left-to-right it is a right-to-left line (`ld-rtl`); if the words run left to right on
        // the page, their ORDER is made logical: reversed, with runs of left-to-right words
        // turned back; each word's glyphs are re-pointed at it and its gap is the space to
        // the word that follows it in that order.
        int w = wfst;
        int nr = 0;
        int nl = 0;
        int j = 0;
        int cl = 0;
        int a = 0;
        int z = 0;
        int g0 = 0;
        int gn = 0;
        while (w <= wlst) {
            g0 = Evidence.WdGet(wd, w, Evidence.WfGfirst());
            gn = Evidence.WdGet(wd, w, Evidence.WfGcount());
            j = 0;
            while (j < gn) {
                cl = PcGcls(gl, g0 + j);
                if (cl == 1) {
                    nr += 1;
                }
                if (cl == 2) {
                    nl += 1;
                }
                j += 1;
            }
            w += 1;
        }
        if (nr <= nl) {
            return 0;
        }
        Evidence.LnSet(ln, lidx, Evidence.LfDir(), Evidence.LdRtl());
        if (PcAxis(Evidence.GlGet(gl, Evidence.WdGet(wd, wfst, Evidence.WfGfirst()), Evidence.GfRot())) != 0) {
            return 0;
        }
        if (Evidence.WdGet(wd, wlst, Evidence.WfX0()) < Evidence.WdGet(wd, wfst, Evidence.WfX0())) {
            return 0;
        }
        if (wfst == wlst) {
            return 0;
        }
        PcRevRows(wd, wfst, wlst);
        a = wfst;
        while (a <= wlst) {
            if (PcWcls(gl, wd, a) == 2) {
                z = a;
                while ((z < wlst) && (PcWcls(gl, wd, z + 1) == 2)) {
                    z += 1;
                }
                PcRevRows(wd, a, z);
                a = z + 1;
            } else {
                a += 1;
            }
        }
        w = wfst;
        while (w <= wlst) {
            g0 = Evidence.WdGet(wd, w, Evidence.WfGfirst());
            gn = Evidence.WdGet(wd, w, Evidence.WfGcount());
            j = 0;
            while (j < gn) {
                Evidence.GlSet(gl, g0 + j, Evidence.GfWord(), w);
                j += 1;
            }
            z = -1;
            if (w < wlst) {
                z = Evidence.WdGet(wd, w, Evidence.WfX0()) - Evidence.WdGet(wd, w + 1, Evidence.WfX1());
            }
            Evidence.WdSet(wd, w, Evidence.WfGap(), z);
            w += 1;
        }
        return 0;
    }
    public static int PcGroup(emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells wd, emon.Port.Cells ln, int page, int g0, int w0) {
        // Group the glyphs from g0 on into words, and the words from w0 on into lines.
        int g1 = Evidence.GlCount(gl);
        int i = g0;
        int cur = -1;
        while (i < g1) {
            if (PcSpaceCp(Evidence.GlGet(gl, i, Evidence.GfCp())) == 1) {
                if (cur >= 0) {
                    PcEmitWord(gl, et, wd, page, cur, i - 1);
                    cur = -1;
                }
            } else {
                if (cur >= 0) {
                    if (PcContinues(gl, i - 1, i) == 0) {
                        PcEmitWord(gl, et, wd, page, cur, i - 1);
                        cur = -1;
                    }
                }
                if (cur < 0) {
                    cur = i;
                }
            }
            i += 1;
        }
        if (cur >= 0) {
            PcEmitWord(gl, et, wd, page, cur, g1 - 1);
            cur = -1;
        }
        // Lines: consecutive words on one baseline, in order.
        int nw = Evidence.WdCount(wd);
        int j = w0;
        int lfirst = -1;
        int prev = -1;
        int lnx = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        int gf0 = 0;
        int gfp = 0;
        int glast = 0;
        int axis = 0;
        int joins = 0;
        int gap = 0;
        int sz = 0;
        int off = 0;
        while (j <= nw) {
            joins = 0;
            if ((j < nw) && (prev >= 0)) {
                gf0 = Evidence.WdGet(wd, j, Evidence.WfGfirst());
                gfp = Evidence.WdGet(wd, prev, Evidence.WfGfirst());
                axis = PcAxis(Evidence.GlGet(gl, gfp, Evidence.GfRot()));
                if (PcRotSame(Evidence.GlGet(gl, gfp, Evidence.GfRot()), Evidence.GlGet(gl, gf0, Evidence.GfRot())) == 1) {
                    sz = Evidence.GlGet(gl, gf0, Evidence.GfSize());
                    if (Evidence.GlGet(gl, gfp, Evidence.GfSize()) > sz) {
                        sz = Evidence.GlGet(gl, gfp, Evidence.GfSize());
                    }
                    if (sz > 200000) {
                        sz = 200000;
                    }
                    if (sz < (0 - 200000)) {
                        sz = 0 - 200000;
                    }
                    glast = (Evidence.WdGet(wd, prev, Evidence.WfGfirst()) + Evidence.WdGet(wd, prev, Evidence.WfGcount())) - 1;
                    off = PcCl(PcPairOff(gl, glast, gf0, axis));
                    // The gap is between the previous word's LAST glyph and this word's first.
                    gap = PcCl(PcPairGap(gl, glast, gf0, axis, sz));
                    if ((off * 1000) <= (sz * OffsetPm)) {
                        if ((gap * 1000) >= (0 - (sz * LineBackPm))) {
                            if ((gap * 1000) <= (sz * LineGapPm)) {
                                joins = 1;
                            }
                        }
                    }
                }
            }
            if (joins == 1) {
                Evidence.WdSet(wd, prev, Evidence.WfGap(), gap);
                prev = j;
            } else {
                // The line so far ends at `prev`: record it, then start a new one at j.
                if (lfirst >= 0) {
                    x0 = Evidence.WdGet(wd, lfirst, Evidence.WfX0());
                    y0 = Evidence.WdGet(wd, lfirst, Evidence.WfY0());
                    x1 = Evidence.WdGet(wd, lfirst, Evidence.WfX1());
                    y1 = Evidence.WdGet(wd, lfirst, Evidence.WfY1());
                    lnx = lfirst;
                    while (lnx <= prev) {
                        if (Evidence.WdGet(wd, lnx, Evidence.WfX0()) < x0) {
                            x0 = Evidence.WdGet(wd, lnx, Evidence.WfX0());
                        }
                        if (Evidence.WdGet(wd, lnx, Evidence.WfY0()) < y0) {
                            y0 = Evidence.WdGet(wd, lnx, Evidence.WfY0());
                        }
                        if (Evidence.WdGet(wd, lnx, Evidence.WfX1()) > x1) {
                            x1 = Evidence.WdGet(wd, lnx, Evidence.WfX1());
                        }
                        if (Evidence.WdGet(wd, lnx, Evidence.WfY1()) > y1) {
                            y1 = Evidence.WdGet(wd, lnx, Evidence.WfY1());
                        }
                        lnx += 1;
                    }
                    gfp = Evidence.WdGet(wd, lfirst, Evidence.WfGfirst());
                    axis = PcAxis(Evidence.GlGet(gl, gfp, Evidence.GfRot()));
                    lnx = Evidence.LnNew(ln, page, x0, y0, x1, y1, lfirst, (prev - lfirst) + 1, PcOffset(gl, gfp, axis));
                    Evidence.LnSet(ln, lnx, Evidence.LfRot(), Evidence.GlGet(gl, gfp, Evidence.GfRot()));
                    PcLineBidi(gl, wd, ln, lnx, lfirst, prev);
                    gfp = lfirst;
                    while (gfp <= prev) {
                        Evidence.WdSet(wd, gfp, Evidence.WfLine(), lnx);
                        gfp += 1;
                    }
                }
                lfirst = j;
                prev = j;
            }
            j += 1;
        }
        return 0;
    }
    internal static int PcBeginPage(emon.Port.Cells cx, int page) {
        // Reset everything a page owns; the fonts (the document's) stay.
        emon.Port.CellsSet(cx, CPage, page);
        emon.Port.CellsSet(cx, CWarn, 0);
        emon.Port.CellsSet(cx, COps, 0);
        emon.Port.CellsSet(cx, CAbort, 0);
        emon.Port.CellsSet(cx, CPos, 0);
        emon.Port.CellsSet(cx, CEnd, 0);
        emon.Port.CellsSet(cx, COxn, 0);
        emon.Port.CellsSet(cx, CCdepth, 0);
        emon.Port.CellsSet(cx, COp, 0);
        emon.Port.CellsSet(cx, CRes, 0);
        emon.Port.CellsSet(cx, CSlot, -1);
        emon.Port.CellsSet(cx, CDepth, 0);
        emon.Port.CellsSet(cx, CFdepth, 0);
        emon.Port.CellsSet(cx, CStm, 0);
        emon.Port.CellsSet(cx, CMctop, -1);
        emon.Port.CellsSet(cx, CMcdepth, 0);
        emon.Port.CellsSet(cx, CMcbase, 0);
        emon.Port.CellsSet(cx, CMcover, 0);
        emon.Port.CellsSet(cx, CCurmcid, -1);
        emon.Port.CellsSet(cx, CCurart, 0);
        emon.Port.CellsSet(cx, CIntext, 0);
        emon.Port.CellsSet(cx, CGsbase, 0);
        Fx.MxIdent(cx, CTm);
        Fx.MxIdent(cx, CTlm);
        Fx.MxIdent(cx, CM);
        return 0;
    }
    public static int PcPage(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells sp, emon.Port.Cells pg, int pi, int page, emon.Port.Cells wd, emon.Port.Cells ln) {
        // Interpret page index pi of the page table pg (page number `page`, 1-based, is
        // what the evidence records): its content streams, then the words and lines.
        // Answers 0, or 7 (`need-bytes`) when the source missed: then nothing written is
        // to be used and the caller re-runs on a fresh view (D075).
        int con = Pdfdoc.PdPgContents(pg, pi);
        int g0 = Evidence.GlCount(gl);
        int w0 = Evidence.WdCount(wd);
        int el = 0;
        int eh = 0;
        int endcs = 0;
        PcBeginPage(cx, page);
        PcBaseMatrix(cx, Pdfdoc.PdPgCrop(pg, pi, 0), Pdfdoc.PdPgCrop(pg, pi, 1), Pdfdoc.PdPgCrop(pg, pi, 2), Pdfdoc.PdPgCrop(pg, pi, 3), Pdfdoc.PdPgRotate(pg, pi));
        PcGsReset(cx);
        emon.Port.CellsSet(cx, CRes, Pdfdoc.PdPgResources(pg, pi));
        emon.Port.CellsDrop(cs, 0);
        if (con != 0) {
            if (Pdflex.PlKindOf(ar, con) == 8) {
                PcAppendStream(src, ar, dc, a, b, st, cx, @out, cs, con);
            }
            if (Pdflex.PlKindOf(ar, con) == 6) {
                el = Pdflex.PlFirst(ar, con);
                while ((el != 0) && (emon.Port.CellsAt(cx, CAbort) == 0)) {
                    eh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, el);
                    if (Pdfsrc.PsMissed(src)) {
                        emon.Port.CellsSet(cx, CAbort, 1);
                    }
                    if ((eh != 0) && (Pdflex.PlKindOf(ar, eh) == 8)) {
                        PcAppendStream(src, ar, dc, a, b, st, cx, @out, cs, eh);
                    }
                    el = Pdflex.PlNext(ar, el);
                }
            }
        }
        if (emon.Port.CellsAt(cx, CAbort) == 1) {
            return 7;
        }
        endcs = emon.Port.CellsLen(cs);
        PcRun(src, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, sp, 0, endcs);
        if (emon.Port.CellsAt(cx, CAbort) == 1) {
            return 7;
        }
        if (Pdfsrc.PsMissed(src)) {
            return 7;
        }
        PcGroup(gl, et, wd, ln, page, g0, w0);
        return 0;
    }
    public static int PcDocument(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells sp, emon.Port.Cells pg, emon.Port.Cells wd, emon.Port.Cells ln) {
        // Every page of an opened document (`pd-open` has answered 0): clears `cx`,
        // then `pc-page` for each page. Answers 0, or 7 when the source missed.
        PcInit(cx, ox);
        int n = Pdfdoc.PdPages(src, ar, dc, a, b, st, pg);
        int i = 0;
        int status = 0;
        if (n < 0) {
            return 7;
        }
        while (i < n) {
            status = PcPage(src, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, sp, pg, i, i + 1, wd, ln);
            if (status == 7) {
                return 7;
            }
            i += 1;
        }
        return 0;
    }
}
